ENTRIES = tuple(Entry(d['category'],d['term'],d['korean'],tuple(d['aliases'])) for d in _DATA)

# Exact-match dictionaries.  Keep abbreviations that collide with ordinary
# English or other game terms out of unconditional text-substitution.
AMBIGUOUS = frozenset({
    'cs','r','a','l','lf','pc','am','bm','mm','bs','ee','ho','bb','ma','wa',
    'gs','gs1','gs2','ht','otw','pot','cold','warm','train','slot','clean',
    'level','ks','cc','mc','fm','sair','rog','heimes','pt','c2','cc#',
})

def all_index() -> dict[str, Entry]:
    index: dict[str,Entry] = {}
    for row in ENTRIES:
        for key in (row.term,*row.aliases):
            index.setdefault(key.casefold(),row)
    return index

_INDEX=all_index()

def exact_label(text:str, *, safe_only:bool=False) -> str | None:
    s=re.sub(r'\s+',' ',text.strip()).casefold()
    if safe_only and s in AMBIGUOUS:
        return None
    row=_INDEX.get(s)
    return row.korean if row else None

